package vn.covie.cart.application; import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.databind.JsonNode; import org.springframework.stereotype.Component; import vn.covie.catalog.model.VariantEntity; @Component public class CartItemSnapshotFactory{private final ObjectMapper mapper;public CartItemSnapshotFactory(ObjectMapper mapper){this.mapper=mapper;}public JsonNode snapshot(VariantEntity v){return mapper.createObjectNode().put("variantName",v.getVariantName()).put("variantId",v.getId().toString());}}
